import sys

def main():
    s = sys.stdin.read().split()[0]
    prec = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    out, st = [], []
    for c in s:
        if c == '(':
            st.append(c)
        elif c == ')':
            while st[-1] != '(':
                out.append(st.pop())
            st.pop()
        elif c in prec:
            while st and st[-1] != '(' and (prec[st[-1]] > prec[c] or (prec[st[-1]] == prec[c] and c != '^')):
                out.append(st.pop())
            st.append(c)
        else:
            out.append(c)
    while st:
        out.append(st.pop())
    print(''.join(out))

main()

